#include <stdio.h>

int main(void) {
    int q;
    scanf("%d", &q);
    for (int i = 0; i < q; i++) {
        unsigned long long x, a;
        scanf("%llu %llu", &x, &a);
        if (a == 0 || (a & (a - 1)) != 0) {
            printf("bad alignment\n");
        } else {
            printf("%llu\n", (x + a - 1) & ~(a - 1));
        }
    }
    return 0;
}

