#include <stdint.h>
#include <stdio.h>
#include <string.h>

int main(void) {
    int n;
    scanf("%d", &n);
    unsigned char buf[64];
    for (int i = 0; i < n; i++) {
        unsigned value;
        scanf("%x", &value);
        buf[i] = (unsigned char)value;
    }
    int q;
    scanf("%d", &q);
    for (int k = 0; k < q; k++) {
        char type[4];
        int offset;
        scanf("%3s %d", type, &offset);
        int size = type[1] == '1' ? 2 : type[1] == '3' ? 4 : 8;
        if (offset + size > n) {
            printf("out of range\n");
        } else if (size == 2) {
            int16_t v;
            memcpy(&v, buf + offset, sizeof v);
            printf("%d\n", v);
        } else if (size == 4) {
            int32_t v;
            memcpy(&v, buf + offset, sizeof v);
            printf("%ld\n", (long)v);
        } else {
            int64_t v;
            memcpy(&v, buf + offset, sizeof v);
            printf("%lld\n", (long long)v);
        }
    }
    return 0;
}

